\mathsf{IndSat}_{\perp}
=
\{(M,V,X,\operatorname{ind}(\vec t,\vec u,\vec v)):
(M,V,X)\in\mathsf{Team}^{\perp}
\land
\operatorname{FV}(\operatorname{ind}(\vec t,\vec u,\vec v))\subseteq V
\land
\forall s,s'\in X\
(⟦\vec t⟧_{M,s}=⟦\vec t⟧_{M,s'}
\Rightarrow
\exists s''\in X\
(⟦\vec t⟧_{M,s''}=⟦\vec t⟧_{M,s}
\land
⟦\vec u⟧_{M,s''}=⟦\vec u⟧_{M,s}
\land
⟦\vec v⟧_{M,s''}=⟦\vec v⟧_{M,s'}))\}.
